#include "2mm.h"


void kernel_2mm(
		double alpha,
		double beta,
		double tmp[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double C[ NJ + 0][NL + 0],
		double D[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B   offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=C   offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=D   offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=tmp   bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=B     bundle=control
#pragma HLS INTERFACE s_axilite port=C     bundle=control
#pragma HLS INTERFACE s_axilite port=D     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;

  int i, j, k;

  // Local buffers to stage data and enable reuse / parallel access
  double A_loc[NI][NK];
  double B_loc[NK][NJ];
  double C_loc[NJ][NL];
  double tmp_loc[NI][NJ];
  double D_loc[NI][NL];
#pragma HLS ARRAY_PARTITION variable=A_loc   cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=B_loc   cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=tmp_loc cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=C_loc   cyclic factor=8 dim=1

  // Load A
  LOAD_A_I:
  for (i = 0; i < ni; i++)
    LOAD_A_K:
    for (k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
      A_loc[i][k] = A[i][k];
    }

  // Load B
  LOAD_B_K:
  for (k = 0; k < nk; k++)
    LOAD_B_J:
    for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      B_loc[k][j] = B[k][j];
    }

  // Load C
  LOAD_C_K:
  for (k = 0; k < nj; k++)
    LOAD_C_J:
    for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      C_loc[k][j] = C[k][j];
    }

  // Load D
  LOAD_D_I:
  for (i = 0; i < ni; i++)
    LOAD_D_J:
    for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      D_loc[i][j] = D[i][j];
    }

  // First matrix multiply: tmp = alpha * A * B
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      {
#pragma HLS PIPELINE II=1
	double acc = 0.0;
	for (k = 0; k < nk; ++k) {
#pragma HLS UNROLL
	  acc += alpha * A_loc[i][k] * B_loc[k][j];
	}
	tmp_loc[i][j] = acc;
      }

  // Second matrix multiply: D = beta * D + tmp * C
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      {
#pragma HLS PIPELINE II=1
	double acc = D_loc[i][j] * beta;
	for (k = 0; k < nj; ++k) {
#pragma HLS UNROLL
	  acc += tmp_loc[i][k] * C_loc[k][j];
	}
	D_loc[i][j] = acc;
      }

  // Store tmp
  STORE_TMP_I:
  for (i = 0; i < ni; i++)
    STORE_TMP_J:
    for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      tmp[i][j] = tmp_loc[i][j];
    }

  // Store D
  STORE_D_I:
  for (i = 0; i < ni; i++)
    STORE_D_J:
    for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      D[i][j] = D_loc[i][j];
    }
}

#include "2mm.h"

extern "C" {
void kernel_2mm(
		double alpha,
		double beta,
		double tmp[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double C[ NJ + 0][NL + 0],
		double D[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B   offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=C   offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=D   offset=slave bundle=gmem4

#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=tmp   bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=B     bundle=control
#pragma HLS INTERFACE s_axilite port=C     bundle=control
#pragma HLS INTERFACE s_axilite port=D     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;

  int i, j, k;


  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      {
#pragma HLS PIPELINE II=1
	tmp[i][j] = 0.0;
	double acc0 = 0.0;
	for (k = 0; k < nk; ++k)
	  acc0 += alpha * A[i][k] * B[k][j];
	tmp[i][j] = acc0;
      }
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      {
#pragma HLS PIPELINE II=1
	double acc1 = D[i][j] * beta;
	for (k = 0; k < nj; ++k)
	  acc1 += tmp[i][k] * C[k][j];
	D[i][j] = acc1;
      }

}
}

#include "3mm.h"


void kernel_3mm(    
		double E[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double F[ NJ + 0][NL + 0],
		double C[ NJ + 0][NM + 0],
		double D[ NM + 0][NL + 0],
		double G[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=E offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=F offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=D offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=G offset=slave bundle=gmem6
#pragma HLS INTERFACE s_axilite port=E bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=F bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=D bundle=control
#pragma HLS INTERFACE s_axilite port=G bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;
    const int nm = NM;

  int i, j, k;

  // Local staging buffers to enable reuse and parallel access
  static double l_A[NI][NK];
  static double l_B[NK][NJ];
  static double l_E[NI][NJ];
  static double l_C[NJ][NM];
  static double l_D[NM][NL];
  static double l_F[NJ][NL];
  static double l_G[NI][NL];
#pragma HLS ARRAY_PARTITION variable=l_A cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_B cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_C cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_D cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_E cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=l_F cyclic factor=8 dim=1

  // Load A
  for (i = 0; i < ni; i++)
    for (k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
      l_A[i][k] = A[i][k];
    }

  // Load B
  for (k = 0; k < nk; k++)
    for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      l_B[k][j] = B[k][j];
    }

  // Load C
  for (i = 0; i < nj; i++)
    for (k = 0; k < nm; k++) {
#pragma HLS PIPELINE II=1
      l_C[i][k] = C[i][k];
    }

  // Load D
  for (k = 0; k < nm; k++)
    for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      l_D[k][j] = D[k][j];
    }

  // E = A * B
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      {
#pragma HLS PIPELINE II=1
	double acc = 0.0;
	for (k = 0; k < nk; ++k) {
#pragma HLS UNROLL
	  acc += l_A[i][k] * l_B[k][j];
	}
	l_E[i][j] = acc;
      }

  // F = C * D
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      {
#pragma HLS PIPELINE II=1
	double acc = 0.0;
	for (k = 0; k < nm; ++k) {
#pragma HLS UNROLL
	  acc += l_C[i][k] * l_D[k][j];
	}
	l_F[i][j] = acc;
      }

  // G = E * F
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      {
#pragma HLS PIPELINE II=1
	double acc = 0.0;
	for (k = 0; k < nj; ++k) {
#pragma HLS UNROLL
	  acc += l_E[i][k] * l_F[k][j];
	}
	l_G[i][j] = acc;
      }

  // Store E
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      E[i][j] = l_E[i][j];
    }

  // Store F
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      F[i][j] = l_F[i][j];
    }

  // Store G
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      G[i][j] = l_G[i][j];
    }
}

#include "3mm.h"

extern "C" {
void kernel_3mm(
		double E[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double F[ NJ + 0][NL + 0],
		double C[ NJ + 0][NM + 0],
		double D[ NM + 0][NL + 0],
		double G[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=E offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=F offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=D offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=G offset=slave bundle=gmem6
#pragma HLS INTERFACE s_axilite port=E bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=F bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=D bundle=control
#pragma HLS INTERFACE s_axilite port=G bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;
    const int nm = NM;

  int i, j, k;

  // E := A * B
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      {
#pragma HLS PIPELINE II=1
	E[i][j] = 0.0;
	double acc = 0.0;
	for (k = 0; k < nk; ++k)
	  acc += A[i][k] * B[k][j];
	E[i][j] = acc;
      }

  // F := C * D
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      {
#pragma HLS PIPELINE II=1
	F[i][j] = 0.0;
	double acc = 0.0;
	for (k = 0; k < nm; ++k)
	  acc += C[i][k] * D[k][j];
	F[i][j] = acc;
      }

  // G := E * F
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      {
#pragma HLS PIPELINE II=1
	G[i][j] = 0.0;
	double acc = 0.0;
	for (k = 0; k < nj; ++k)
	  acc += E[i][k] * F[k][j];
	G[i][j] = acc;
      }

}
}

#include "atax.h"


void kernel_atax( 
		 double A[ M + 0][N + 0],
		 double x[ N + 0],
		 double y[ N + 0],
		 double tmp[ M + 0])
{
#pragma HLS INLINE off

    const int m = M;
    const int n = N;

  int i, j;

  init_y: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    y[i] = 0;
  }

  outer: for (i = 0; i < m; i++)
    {
      double tmp_local = 0.0;

      inner1: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
	tmp_local = tmp_local + A[i][j] * x[j];
      }
      tmp[i] = tmp_local;

      inner2: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
	y[j] = y[j] + A[i][j] * tmp_local;
      }
    }

}

extern "C" {
void workload(
		 double A[ M + 0][N + 0],
		 double x[ N + 0],
		 double y[ N + 0],
		 double tmp[ M + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=tmp bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_atax(A, x, y, tmp);
}
}

#include "atax.h"

extern "C" {
void kernel_atax(
		 double A[ M + 0][N + 0],
		 double x[ N + 0],
		 double y[ N + 0],
		 double tmp[ M + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=y   offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=A   bundle=control
#pragma HLS INTERFACE s_axilite port=x   bundle=control
#pragma HLS INTERFACE s_axilite port=y   bundle=control
#pragma HLS INTERFACE s_axilite port=tmp bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int m = M;
    const int n = N;

  int i, j;

  // Local buffers for parallel/coalesced access
  double x_local[N];
  double y_local[N];
#pragma HLS ARRAY_PARTITION variable=y_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=8 dim=1

  init_x: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    x_local[i] = x[i];
  }

  init_y: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    y_local[i] = 0;
  }

  main_loop: for (i = 0; i < m; i++)
    {
      double A_row[N];
#pragma HLS ARRAY_PARTITION variable=A_row cyclic factor=8 dim=1

      load_row: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        A_row[j] = A[i][j];
      }

      double t = 0.0;
      compute_tmp: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        t = t + A_row[j] * x_local[j];
      }
      tmp[i] = t;

      update_y: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        y_local[j] = y_local[j] + A_row[j] * t;
      }
    }

  store_y: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    y[i] = y_local[i];
  }

}
}

#include "bicg.h"

extern "C" {
void kernel_bicg(
		 double A[ N + 0][M + 0],
		 double s[ M + 0],
		 double q[ N + 0],
		 double p[ M + 0],
		 double r[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=s offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=q offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=p offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=r offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=s bundle=control
#pragma HLS INTERFACE s_axilite port=q bundle=control
#pragma HLS INTERFACE s_axilite port=p bundle=control
#pragma HLS INTERFACE s_axilite port=r bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int m = M;

    int i, j;

    // Local staging buffers for reuse and parallel access
    double s_local[M];
    double p_local[M];
    double r_local[N];
    double q_local[N];
#pragma HLS ARRAY_PARTITION variable=s_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=p_local cyclic factor=8 dim=1

    // Load p into local buffer
  load_p:
    for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
        p_local[j] = p[j];
    }

    // Load r into local buffer
  load_r:
    for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        r_local[i] = r[i];
    }

    // Initialize s
  init_s:
    for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
        s_local[i] = 0.0;
    }

  outer:
    for (i = 0; i < n; i++)
    {
        double q_acc = 0.0;
        double r_i = r_local[i];
      inner:
        for (j = 0; j < m; j++)
        {
#pragma HLS PIPELINE II=1
            double a = A[i][j];
            s_local[j] = s_local[j] + r_i * a;
            q_acc = q_acc + a * p_local[j];
        }
        q_local[i] = q_acc;
    }

    // Write back results
  store_s:
    for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
        s[j] = s_local[j];
    }

  store_q:
    for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        q[i] = q_local[i];
    }
}
}

#include "bicg.h"

extern "C" {
void kernel_bicg(
		 double A[ N + 0][M + 0],
		 double s[ M + 0],
		 double q[ N + 0],
		 double p[ M + 0],
		 double r[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=s offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=q offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=p offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=r offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=s bundle=control
#pragma HLS INTERFACE s_axilite port=q bundle=control
#pragma HLS INTERFACE s_axilite port=p bundle=control
#pragma HLS INTERFACE s_axilite port=r bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int m = M;

  int i, j;

  // Local buffers for efficient on-chip access
  double s_local[M];
  double p_local[M];
#pragma HLS ARRAY_PARTITION variable=s_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=p_local cyclic factor=8 dim=1

  init_s:
  for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
    s_local[i] = 0;
  }

  load_p:
  for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
    p_local[j] = p[j];
  }

  outer:
  for (i = 0; i < n; i++)
    {
      double q_acc = 0.0;
      double r_i = r[i];

      inner:
      for (j = 0; j < m; j++)
	{
#pragma HLS PIPELINE II=1
	  double a = A[i][j];
	  s_local[j] = s_local[j] + r_i * a;
	  q_acc = q_acc + a * p_local[j];
	}

      q[i] = q_acc;
    }

  store_s:
  for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
    s[i] = s_local[i];
  }

}
}

#include "cholesky.h"


void kernel_cholesky(
		     double A[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;


  for (i = 0; i < n; i++) {

     for (j = 0; j < i; j++) {
        double acc = A[i][j];
        for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
           acc -= A[i][k] * A[j][k];
        }
        A[i][j] = acc / A[j][j];
     }

     double diag = A[i][i];
     for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
        diag -= A[i][k] * A[i][k];
     }
     A[i][i] = sqrt(diag);
  }

}

#include "cholesky.h"

extern "C" {
void kernel_cholesky(
		     double A[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;

  for (i = 0; i < n; i++) {

     for (j = 0; j < i; j++) {
        for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
           A[i][j] -= A[i][k] * A[j][k];
        }
        A[i][j] /= A[j][j];
     }

     for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
        A[i][i] -= A[i][k] * A[i][k];
     }
     A[i][i] = sqrt(A[i][i]);
  }

}
}

#include "correlation.h"

void kernel_correlation( 
			double float_n,
			double data[ N + 0][M + 0],
			double corr[ M + 0][M + 0],
			double mean[ M + 0],
			double stddev[ M + 0])
{
#pragma HLS INTERFACE m_axi port=data   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=corr   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=mean   offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=stddev offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=float_n bundle=control
#pragma HLS INTERFACE s_axilite port=data    bundle=control
#pragma HLS INTERFACE s_axilite port=corr    bundle=control
#pragma HLS INTERFACE s_axilite port=mean    bundle=control
#pragma HLS INTERFACE s_axilite port=stddev  bundle=control
#pragma HLS INTERFACE s_axilite port=return  bundle=control

    const int n = N;
    const int m = M;

  int i, j, k;

  double eps = 0.1;

  // Local working buffers staged from global memory for reuse across phases
  static double data_l[N][M];
#pragma HLS ARRAY_PARTITION variable=data_l cyclic factor=8 dim=2
  static double mean_l[M];
  static double stddev_l[M];

  // Stage data into local memory
  LOAD_I: for (i = 0; i < n; i++)
    LOAD_J: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
      data_l[i][j] = data[i][j];
    }

  // Mean computation
  MEAN_J: for (j = 0; j < m; j++)
    {
      double acc = 0.0;
      MEAN_I: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        acc += data_l[i][j];
      }
      mean_l[j] = acc / float_n;
    }

  // Standard deviation computation
  STD_J: for (j = 0; j < m; j++)
    {
      double acc = 0.0;
      double mj = mean_l[j];
      STD_I: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        double diff = data_l[i][j] - mj;
        acc += diff * diff;
      }
      acc /= float_n;
      acc = sqrt(acc);
      stddev_l[j] = acc <= eps ? 1.0 : acc;
    }

  // Center and normalize the data matrix
  double sqrt_fn = sqrt(float_n);
  NORM_I: for (i = 0; i < n; i++)
    NORM_J: for (j = 0; j < m; j++)
      {
#pragma HLS PIPELINE II=1
        double v = data_l[i][j] - mean_l[j];
        v /= sqrt_fn * stddev_l[j];
        data_l[i][j] = v;
      }

  // Correlation matrix
  CORR_I: for (i = 0; i < m-1; i++)
    {
      corr[i][i] = 1.0;
      CORR_J: for (j = i+1; j < m; j++)
        {
          double acc = 0.0;
          CORR_K: for (k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
            acc += (data_l[k][i] * data_l[k][j]);
          }
          corr[i][j] = acc;
          corr[j][i] = acc;
        }
    }
  corr[m-1][m-1] = 1.0;

  // Write back centered/normalized data and statistics
  STORE_I: for (i = 0; i < n; i++)
    STORE_J: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
      data[i][j] = data_l[i][j];
    }

  STORE_STATS: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
    mean[j]   = mean_l[j];
    stddev[j] = stddev_l[j];
  }
}

#include "correlation.h"

extern "C" {
void kernel_correlation(
			double float_n,
			double data[ N + 0][M + 0],
			double corr[ M + 0][M + 0],
			double mean[ M + 0],
			double stddev[ M + 0])
{
#pragma HLS INTERFACE m_axi port=data offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=corr offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=mean offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=stddev offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=float_n bundle=control
#pragma HLS INTERFACE s_axilite port=data bundle=control
#pragma HLS INTERFACE s_axilite port=corr bundle=control
#pragma HLS INTERFACE s_axilite port=mean bundle=control
#pragma HLS INTERFACE s_axilite port=stddev bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int m = M;

  int i, j, k;

  double eps = 0.1;


  mean_loop_j: for (j = 0; j < m; j++)
    {
      mean[j] = 0.0;
      mean_loop_i: for (i = 0; i < n; i++)
      {
#pragma HLS PIPELINE II=1
	mean[j] += data[i][j];
      }
      mean[j] /= float_n;
    }


   stddev_loop_j: for (j = 0; j < m; j++)
    {
      stddev[j] = 0.0;
      stddev_loop_i: for (i = 0; i < n; i++)
      {
#pragma HLS PIPELINE II=1
        stddev[j] += (data[i][j] - mean[j]) * (data[i][j] - mean[j]);
      }
      stddev[j] /= float_n;
      stddev[j] = sqrt(stddev[j]);


      stddev[j] = stddev[j] <= eps ? 1.0 : stddev[j];
    }


  norm_loop_i: for (i = 0; i < n; i++)
    norm_loop_j: for (j = 0; j < m; j++)
      {
#pragma HLS PIPELINE II=1
        data[i][j] -= mean[j];
        data[i][j] /= sqrt(float_n) * stddev[j];
      }


  corr_loop_i: for (i = 0; i < m-1; i++)
    {
      corr[i][i] = 1.0;
      corr_loop_j: for (j = i+1; j < m; j++)
        {
          double acc = 0.0;
          corr_loop_k: for (k = 0; k < n; k++)
          {
#pragma HLS PIPELINE II=1
            acc += (data[k][i] * data[k][j]);
          }
          corr[i][j] = acc;
          corr[j][i] = acc;
        }
    }
  corr[m-1][m-1] = 1.0;

}
}

#include "covariance.h"

extern "C" {
void kernel_covariance( 
		       double float_n,
		       double data[ N + 0][M + 0],
		       double cov[ M + 0][M + 0],
		       double mean[ M + 0])
{
#pragma HLS INTERFACE m_axi port=data offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=cov  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=mean offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=float_n bundle=control
#pragma HLS INTERFACE s_axilite port=data    bundle=control
#pragma HLS INTERFACE s_axilite port=cov     bundle=control
#pragma HLS INTERFACE s_axilite port=mean    bundle=control
#pragma HLS INTERFACE s_axilite port=return  bundle=control

    const int n = N;
    const int m = M;

  int i, j, k;

  // Local buffers for reuse and partitioned parallel access
  static double l_mean[M];
  static double l_data[N][M];
#pragma HLS ARRAY_PARTITION variable=l_mean complete dim=1
#pragma HLS ARRAY_PARTITION variable=l_data cyclic factor=8 dim=2

  // Stage input data into local buffer
  LOAD_I: for (i = 0; i < n; i++)
    LOAD_J: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
      l_data[i][j] = data[i][j];
    }

  // Compute mean per column
  MEAN_J: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
    double acc = 0.0;
    MEAN_I: for (i = 0; i < n; i++) {
      acc += l_data[i][j];
    }
    l_mean[j] = acc / float_n;
  }

  // Subtract mean
  SUB_I: for (i = 0; i < n; i++)
    SUB_J: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
      l_data[i][j] -= l_mean[j];
    }

  // Covariance computation
  COV_I: for (i = 0; i < m; i++)
    COV_J: for (j = i; j < m; j++)
      {
        double acc = 0.0;
        COV_K: for (k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
	  acc += l_data[k][i] * l_data[k][j];
        }
        double val = acc / (float_n - 1.0);
        cov[i][j] = val;
        cov[j][i] = val;
      }

  // Write mean back
  STORE_MEAN: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
    mean[j] = l_mean[j];
  }

  // Write modified data back
  STORE_I: for (i = 0; i < n; i++)
    STORE_J: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
      data[i][j] = l_data[i][j];
    }
}
}

