extern "C" {
void kernel_doitgen(
		    double A[ NR + 0][NQ + 0][NP + 0],
		    double C4[ NP + 0][NP + 0],
		    double sum[ NP + 0])
{
#pragma HLS INTERFACE m_axi port=A  offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=C4 offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=sum offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=A  bundle=control
#pragma HLS INTERFACE s_axilite port=C4 bundle=control
#pragma HLS INTERFACE s_axilite port=sum bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int nr = NR;
    const int nq = NQ;
    const int np = NP;

  int r, q, p, s;

  // Local buffers for parallel access
  double C4_local[NP][NP];
#pragma HLS ARRAY_PARTITION variable=C4_local complete dim=1

  double sum_local[NP];
#pragma HLS ARRAY_PARTITION variable=sum_local complete dim=1

  double A_row[NP];
#pragma HLS ARRAY_PARTITION variable=A_row complete dim=1

  // Cache C4 into local memory once
  for (s = 0; s < np; s++) {
    for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
      C4_local[s][p] = C4[s][p];
    }
  }

  for (r = 0; r < nr; r++) {
    for (q = 0; q < nq; q++)  {

      // Load A[r][q][*] into local registers
      for (s = 0; s < np; s++) {
#pragma HLS PIPELINE II=1
        A_row[s] = A[r][q][s];
      }

      for (p = 0; p < np; p++)  {
#pragma HLS PIPELINE II=1
        double acc = 0.0;
        for (s = 0; s < np; s++) {
#pragma HLS UNROLL
          acc += A_row[s] * C4_local[s][p];
        }
        sum_local[p] = acc;
      }

      for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
        A[r][q][p] = sum_local[p];
        sum[p] = sum_local[p];
      }
    }
  }

}
}

#include "durbin.h"


void kernel_durbin(
		   double r[ N + 0],
		   double y[ N + 0])
{

    const int n = N;

 double z[N];
 double alpha;
 double beta;
 double sum;

 int i,k;

 // Local copies for fast on-chip access and to enable parallel ports
 double r_local[N];
 double y_local[N];
#pragma HLS ARRAY_PARTITION variable=r_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=y_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=z       cyclic factor=8 dim=1

 // Stage inputs into local memory
 load_r:
 for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
   r_local[i] = r[i];
 }

 y_local[0] = -r_local[0];
 beta = 1.0;
 alpha = -r_local[0];

 for (k = 1; k < n; k++) {
   beta = (1-alpha*alpha)*beta;
   sum = 0.0;
   sum_loop:
   for (i=0; i<k; i++) {
#pragma HLS PIPELINE II=1
      sum += r_local[k-i-1]*y_local[i];
   }
   alpha = - (r_local[k] + sum)/beta;

   z_loop:
   for (i=0; i<k; i++) {
#pragma HLS PIPELINE II=1
      z[i] = y_local[i] + alpha*y_local[k-i-1];
   }
   copy_loop:
   for (i=0; i<k; i++) {
#pragma HLS PIPELINE II=1
     y_local[i] = z[i];
   }
   y_local[k] = alpha;
 }

 // Write results back to global memory
 store_y:
 for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
   y[i] = y_local[i];
 }

}


extern "C" {
void workload(
		   double r[ N + 0],
		   double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=r offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=r bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

  kernel_durbin(r, y);
}
}

#include "durbin.h"

extern "C" {
void kernel_durbin(
		   double r[ N + 0],
		   double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=r offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=r bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    double z[N];
    double y_local[N];
    double r_local[N];
#pragma HLS ARRAY_PARTITION variable=z cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=y_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=r_local cyclic factor=8 dim=1

    double alpha;
    double beta;
    double sum;

    int i, k;

    // Load r into local buffer
    load_r:
    for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        r_local[i] = r[i];
    }

    y_local[0] = -r_local[0];
    beta = 1.0;
    alpha = -r_local[0];

    main_loop:
    for (k = 1; k < n; k++) {
        beta = (1 - alpha * alpha) * beta;
        sum = 0.0;
        sum_loop:
        for (i = 0; i < k; i++) {
#pragma HLS PIPELINE II=1
            sum += r_local[k - i - 1] * y_local[i];
        }
        alpha = -(r_local[k] + sum) / beta;

        update_z:
        for (i = 0; i < k; i++) {
#pragma HLS PIPELINE II=1
            z[i] = y_local[i] + alpha * y_local[k - i - 1];
        }
        copy_y:
        for (i = 0; i < k; i++) {
#pragma HLS PIPELINE II=1
            y_local[i] = z[i];
        }
        y_local[k] = alpha;
    }

    // Write back y
    store_y:
    for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        y[i] = y_local[i];
    }
}
}

#include "fdtd-2d.h"


void kernel_fdtd_2d(


		    double ex[ NX + 0][NY + 0],
		    double ey[ NX + 0][NY + 0],
		    double hz[ NX + 0][NY + 0],
		    double _fict_[ TMAX + 0])
{
#pragma HLS INTERFACE m_axi port=ex offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=ey offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=hz offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=_fict_ offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=ex bundle=control
#pragma HLS INTERFACE s_axilite port=ey bundle=control
#pragma HLS INTERFACE s_axilite port=hz bundle=control
#pragma HLS INTERFACE s_axilite port=_fict_ bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int tmax = TMAX;
    const int nx = NX;
    const int ny = NY;

  int t, i, j;


  for(t = 0; t < tmax; t++)
    {
      for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
	ey[0][j] = _fict_[t];
      }
      for (i = 1; i < nx; i++)
	for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
	  ey[i][j] = ey[i][j] - 0.5*(hz[i][j]-hz[i-1][j]);
	}
      for (i = 0; i < nx; i++)
	for (j = 1; j < ny; j++) {
#pragma HLS PIPELINE II=1
	  ex[i][j] = ex[i][j] - 0.5*(hz[i][j]-hz[i][j-1]);
	}
      for (i = 0; i < nx - 1; i++)
	for (j = 0; j < ny - 1; j++) {
#pragma HLS PIPELINE II=1
	  hz[i][j] = hz[i][j] - 0.7*  (ex[i][j+1] - ex[i][j] +
				       ey[i+1][j] - ey[i][j]);
	}
    }

}

