extern "C" {
void kernel_fdtd_2d(
		    double ex[ NX + 0][NY + 0],
		    double ey[ NX + 0][NY + 0],
		    double hz[ NX + 0][NY + 0],
		    double _fict_[ TMAX + 0])
{
#pragma HLS INTERFACE m_axi port=ex     offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=ey     offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=hz     offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=_fict_ offset=slave bundle=gmem3

#pragma HLS INTERFACE s_axilite port=ex     bundle=control
#pragma HLS INTERFACE s_axilite port=ey     bundle=control
#pragma HLS INTERFACE s_axilite port=hz     bundle=control
#pragma HLS INTERFACE s_axilite port=_fict_ bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int tmax = TMAX;
    const int nx = NX;
    const int ny = NY;

  int t, i, j;


  for(t = 0; t < tmax; t++)
    {
    init_ey:
      for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
	ey[0][j] = _fict_[t];
      }

    update_ey_i:
      for (i = 1; i < nx; i++)
      update_ey_j:
	for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
	  ey[i][j] = ey[i][j] - 0.5*(hz[i][j]-hz[i-1][j]);
	}

    update_ex_i:
      for (i = 0; i < nx; i++)
      update_ex_j:
	for (j = 1; j < ny; j++) {
#pragma HLS PIPELINE II=1
	  ex[i][j] = ex[i][j] - 0.5*(hz[i][j]-hz[i][j-1]);
	}

    update_hz_i:
      for (i = 0; i < nx - 1; i++)
      update_hz_j:
	for (j = 0; j < ny - 1; j++) {
#pragma HLS PIPELINE II=1
	  hz[i][j] = hz[i][j] - 0.7*  (ex[i][j+1] - ex[i][j] +
				       ey[i+1][j] - ey[i][j]);
	}
    }

}
}

#include "floyd-warshall.h"


extern "C" {
void kernel_floyd_warshall(
			   int path[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=path bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;

  // Local buffer to stage the matrix for reuse during the k-iterations.
  // This enables fast, partitioned on-chip access for the inner loop.
  static int local_path[N][N];
#pragma HLS ARRAY_PARTITION variable=local_path cyclic factor=16 dim=2

  // Load from global memory into local buffer
  load_rows:
  for (i = 0; i < n; i++) {
    load_cols:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      local_path[i][j] = path[i][j];
    }
  }

  // Core Floyd-Warshall on the local buffer
  k_loop:
  for (k = 0; k < n; k++)
    {
      i_loop:
      for(i = 0; i < n; i++) {
	j_loop:
	for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
	  int via = local_path[i][k] + local_path[k][j];
	  int cur = local_path[i][j];
	  local_path[i][j] = cur < via ? cur : via;
	}
      }
    }

  // Store back to global memory
  store_rows:
  for (i = 0; i < n; i++) {
    store_cols:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      path[i][j] = local_path[i][j];
    }
  }

}
}

#include "floyd-warshall.h"

extern "C" {
void kernel_floyd_warshall(
			   int path[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=path bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;

  for (k = 0; k < n; k++)
    {
      for(i = 0; i < n; i++)
	for (j = 0; j < n; j++)
	  {
#pragma HLS PIPELINE II=1
	  path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
	    path[i][j] : path[i][k] + path[k][j];
	  }
    }

}
}

#include "gemm.h"


void kernel_gemm(  
		 double alpha,
		 double beta,
		 double C[ NI + 0][NJ + 0],
		 double A[ NI + 0][NK + 0],
		 double B[ NK + 0][NJ + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;

    // Local staging buffers to enable reuse and parallel access.
    double A_buf[NI][NK];
    double B_buf[NK][NJ];
    double C_buf[NI][NJ];
#pragma HLS ARRAY_PARTITION variable=A_buf cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=B_buf cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=C_buf cyclic factor=8 dim=2

    int i, j, k;

    // Load A into local buffer.
load_A_i:
    for (i = 0; i < ni; i++) {
    load_A_k:
        for (k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
            A_buf[i][k] = A[i][k];
        }
    }

    // Load B into local buffer.
load_B_k:
    for (k = 0; k < nk; k++) {
    load_B_j:
        for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            B_buf[k][j] = B[k][j];
        }
    }

    // Load C into local buffer.
load_C_i:
    for (i = 0; i < ni; i++) {
    load_C_j:
        for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            C_buf[i][j] = C[i][j];
        }
    }

    // Compute on local buffers.
compute_i:
    for (i = 0; i < ni; i++) {
    scale_j:
        for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            C_buf[i][j] *= beta;
        }
    compute_k:
        for (k = 0; k < nk; k++) {
        compute_j:
            for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
                C_buf[i][j] += alpha * A_buf[i][k] * B_buf[k][j];
            }
        }
    }

    // Store C back to global memory.
store_C_i:
    for (i = 0; i < ni; i++) {
    store_C_j:
        for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] = C_buf[i][j];
        }
    }
}

#include "gemm.h"

extern "C" {
void kernel_gemm(
		 double alpha,
		 double beta,
		 double C[ NI + 0][NJ + 0],
		 double A[ NI + 0][NK + 0],
		 double B[ NK + 0][NJ + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;

    int i, j, k;

    // Local buffer for B (reused across all rows of C)
    static double Bbuf[NK][NJ];
#pragma HLS ARRAY_PARTITION variable=Bbuf cyclic factor=8 dim=2

    // Load B once into local memory
    for (k = 0; k < nk; k++) {
        for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            Bbuf[k][j] = B[k][j];
        }
    }

    for (i = 0; i < ni; i++) {
        // Local row buffers
        double Crow[NJ];
        double Arow[NK];
#pragma HLS ARRAY_PARTITION variable=Crow cyclic factor=8 dim=1

        // Load A row
        for (k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
            Arow[k] = A[i][k];
        }

        // Scale C row by beta
        for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            Crow[j] = C[i][j] * beta;
        }

        // Accumulate: iterate over k outer, j inner.
        // Inner loop over j has no inter-iteration dependence -> II=1
        for (k = 0; k < nk; k++) {
            double a_alpha = alpha * Arow[k];
            for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
                Crow[j] += a_alpha * Bbuf[k][j];
            }
        }

        // Write C row back
        for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] = Crow[j];
        }
    }
}
}

#include "gemver.h"


extern "C" {
void kernel_gemver(
		   double alpha,
		   double beta,
		   double A[ N + 0][N + 0],
		   double u1[ N + 0],
		   double v1[ N + 0],
		   double u2[ N + 0],
		   double v2[ N + 0],
		   double w[ N + 0],
		   double x[ N + 0],
		   double y[ N + 0],
		   double z[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=u1  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=v1  offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=u2  offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=v2  offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=w   offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=x   offset=slave bundle=gmem6
#pragma HLS INTERFACE m_axi port=y   offset=slave bundle=gmem7
#pragma HLS INTERFACE m_axi port=z   offset=slave bundle=gmem8

#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=u1    bundle=control
#pragma HLS INTERFACE s_axilite port=v1    bundle=control
#pragma HLS INTERFACE s_axilite port=u2    bundle=control
#pragma HLS INTERFACE s_axilite port=v2    bundle=control
#pragma HLS INTERFACE s_axilite port=w     bundle=control
#pragma HLS INTERFACE s_axilite port=x     bundle=control
#pragma HLS INTERFACE s_axilite port=y     bundle=control
#pragma HLS INTERFACE s_axilite port=z     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    int i, j;

    // Local staging buffers to enable reuse, pipelining, and parallel access.
    double A_loc[N][N];
#pragma HLS ARRAY_PARTITION variable=A_loc cyclic factor=8 dim=2

    double u1_loc[N];
    double v1_loc[N];
    double u2_loc[N];
    double v2_loc[N];
    double w_loc[N];
    double x_loc[N];
    double y_loc[N];
    double z_loc[N];
#pragma HLS ARRAY_PARTITION variable=v1_loc cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=v2_loc cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=x_loc  cyclic factor=8 dim=1

    // Load vectors into local memory.
load_vecs:
    for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        u1_loc[i] = u1[i];
        v1_loc[i] = v1[i];
        u2_loc[i] = u2[i];
        v2_loc[i] = v2[i];
        w_loc[i]  = w[i];
        x_loc[i]  = x[i];
        y_loc[i]  = y[i];
        z_loc[i]  = z[i];
    }

    // Load A into local memory.
load_A:
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            A_loc[i][j] = A[i][j];
        }

    // Loop 1: A = A + u1*v1' + u2*v2'
loop1_i:
    for (i = 0; i < n; i++) {
        double u1i = u1_loc[i];
        double u2i = u2_loc[i];
loop1_j:
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            A_loc[i][j] = A_loc[i][j] + u1i * v1_loc[j] + u2i * v2_loc[j];
        }
    }

    // Loop 2: x = x + beta * A' * y
loop2_i:
    for (i = 0; i < n; i++) {
loop2_j:
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            x_loc[i] = x_loc[i] + beta * A_loc[j][i] * y_loc[j];
        }
    }

    // Loop 3: x = x + z
loop3:
    for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x_loc[i] = x_loc[i] + z_loc[i];
    }

    // Loop 4: w = w + alpha * A * x
loop4_i:
    for (i = 0; i < n; i++) {
        double acc = w_loc[i];
loop4_j:
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            acc = acc + alpha * A_loc[i][j] * x_loc[j];
        }
        w_loc[i] = acc;
    }

    // Write results back to global memory.
store_A:
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = A_loc[i][j];
        }

store_vecs:
    for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        w[i] = w_loc[i];
        x[i] = x_loc[i];
    }
}
}

#include "gemver.h"

extern "C" {
void kernel_gemver(
		   double alpha,
		   double beta,
		   double A[ N + 0][N + 0],
		   double u1[ N + 0],
		   double v1[ N + 0],
		   double u2[ N + 0],
		   double v2[ N + 0],
		   double w[ N + 0],
		   double x[ N + 0],
		   double y[ N + 0],
		   double z[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A  offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=u1 offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=v1 offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=u2 offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=v2 offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=w  offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=x  offset=slave bundle=gmem6
#pragma HLS INTERFACE m_axi port=y  offset=slave bundle=gmem7
#pragma HLS INTERFACE m_axi port=z  offset=slave bundle=gmem8

#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=u1    bundle=control
#pragma HLS INTERFACE s_axilite port=v1    bundle=control
#pragma HLS INTERFACE s_axilite port=u2    bundle=control
#pragma HLS INTERFACE s_axilite port=v2    bundle=control
#pragma HLS INTERFACE s_axilite port=w     bundle=control
#pragma HLS INTERFACE s_axilite port=x     bundle=control
#pragma HLS INTERFACE s_axilite port=y     bundle=control
#pragma HLS INTERFACE s_axilite port=z     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j;

  // Local buffers to enable efficient on-chip computation and partitioning
  static double A_loc[N][N];
#pragma HLS ARRAY_PARTITION variable=A_loc cyclic factor=8 dim=2

  static double u1_loc[N], v1_loc[N], u2_loc[N], v2_loc[N];
  static double w_loc[N], x_loc[N], y_loc[N], z_loc[N];
#pragma HLS ARRAY_PARTITION variable=v1_loc cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=v2_loc cyclic factor=8 dim=1

  // Load vectors
  load_vecs:
  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    u1_loc[i] = u1[i];
    v1_loc[i] = v1[i];
    u2_loc[i] = u2[i];
    v2_loc[i] = v2[i];
    w_loc[i]  = w[i];
    x_loc[i]  = x[i];
    y_loc[i]  = y[i];
    z_loc[i]  = z[i];
  }

  // Load A
  load_A_i:
  for (i = 0; i < n; i++) {
    load_A_j:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      A_loc[i][j] = A[i][j];
    }
  }

  // A = A + u1*v1 + u2*v2
  comp1_i:
  for (i = 0; i < n; i++) {
    double u1i = u1_loc[i];
    double u2i = u2_loc[i];
    comp1_j:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      A_loc[i][j] = A_loc[i][j] + u1i * v1_loc[j] + u2i * v2_loc[j];
    }
  }

  // x = x + beta * A^T * y
  comp2_i:
  for (i = 0; i < n; i++) {
    double acc = x_loc[i];
    comp2_j:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      acc = acc + beta * A_loc[j][i] * y_loc[j];
    }
    x_loc[i] = acc;
  }

  // x = x + z
  comp3:
  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    x_loc[i] = x_loc[i] + z_loc[i];
  }

  // w = w + alpha * A * x
  comp4_i:
  for (i = 0; i < n; i++) {
    double acc = w_loc[i];
    comp4_j:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      acc = acc + alpha * A_loc[i][j] * x_loc[j];
    }
    w_loc[i] = acc;
  }

  // Store results back
  store_A_i:
  for (i = 0; i < n; i++) {
    store_A_j:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      A[i][j] = A_loc[i][j];
    }
  }

  store_vecs:
  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    w[i] = w_loc[i];
    x[i] = x_loc[i];
  }
}
}

#include "gesummv.h"


void kernel_gesummv(
		    double alpha,
		    double beta,
		    double A[ N + 0][N + 0],
		    double B[ N + 0][N + 0],
		    double tmp[ N + 0],
		    double x[ N + 0],
		    double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=tmp bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j;

  // Stage x into a local buffer for reuse across all rows
  double x_local[N];
#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=8 dim=1
  for (int k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
    x_local[k] = x[k];
  }

  for (i = 0; i < n; i++)
    {
      double tmp_acc = 0.0;
      double y_acc = 0.0;

      // Stage current rows of A and B into local buffers for parallel access
      double A_row[N];
      double B_row[N];
#pragma HLS ARRAY_PARTITION variable=A_row cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=B_row cyclic factor=8 dim=1

      for (int k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
        A_row[k] = A[i][k];
        B_row[k] = B[i][k];
      }

      for (j = 0; j < n; j++)
	{
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
	  tmp_acc = A_row[j] * x_local[j] + tmp_acc;
	  y_acc = B_row[j] * x_local[j] + y_acc;
	}

      tmp[i] = tmp_acc;
      y[i] = alpha * tmp_acc + beta * y_acc;
    }

}

#include "gesummv.h"

void kernel_gesummv(
		    double alpha,
		    double beta,
		    double A[ N + 0][N + 0],
		    double B[ N + 0][N + 0],
		    double tmp[ N + 0],
		    double x[ N + 0],
		    double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=tmp bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    int i, j;

    // Local buffer for x to enable parallel access in the inner loop
    double x_local[N];
#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=8 dim=1

    for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x_local[i] = x[i];
    }

    for (i = 0; i < n; i++) {
        double tmp_acc = 0.0;
        double y_acc = 0.0;

    inner_loop:
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            tmp_acc = A[i][j] * x_local[j] + tmp_acc;
            y_acc = B[i][j] * x_local[j] + y_acc;
        }

        tmp[i] = tmp_acc;
        y[i] = alpha * tmp_acc + beta * y_acc;
    }
}

#include "gramschmidt.h"


void kernel_gramschmidt( 
			double A[ M + 0][N + 0],
			double R[ N + 0][N + 0],
			double Q[ M + 0][N + 0])
{
#pragma HLS INLINE off

    const int m = M;
    const int n = N;

  int i, j, k;

  double nrm;

  for (k = 0; k < n; k++)
    {
      nrm = 0.0;
    nrm_loop:
      for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
        nrm += A[i][k] * A[i][k];
      }
      R[k][k] = sqrt(nrm);

    q_loop:
      for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
        Q[i][k] = A[i][k] / R[k][k];
      }

    j_loop:
      for (j = k + 1; j < n; j++)
	{
	  double r_acc = 0.0;
	dot_loop:
	  for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
	    r_acc += Q[i][k] * A[i][j];
	  }
	  R[k][j] = r_acc;

	update_loop:
	  for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
	    A[i][j] = A[i][j] - Q[i][k] * r_acc;
	  }
	}
    }

}

extern "C" {
void workload(
			double A[ M + 0][N + 0],
			double R[ N + 0][N + 0],
			double Q[ M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=R offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=Q offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=R bundle=control
#pragma HLS INTERFACE s_axilite port=Q bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_gramschmidt(A, R, Q);
}
}

#include "gramschmidt.h"

extern "C" {
void kernel_gramschmidt(
			double A[ M + 0][N + 0],
			double R[ N + 0][N + 0],
			double Q[ M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=R offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=Q offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=R bundle=control
#pragma HLS INTERFACE s_axilite port=Q bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int m = M;
    const int n = N;

  int i, j, k;

  double nrm;

  for (k = 0; k < n; k++)
    {
      nrm = 0.0;
    nrm_loop:
      for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
        nrm += A[i][k] * A[i][k];
      }
      R[k][k] = sqrt(nrm);
    q_loop:
      for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
        Q[i][k] = A[i][k] / R[k][k];
      }
    j_loop:
      for (j = k + 1; j < n; j++)
	{
	  R[k][j] = 0.0;
	  double r_acc = 0.0;
	r_loop:
	  for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
	    r_acc += Q[i][k] * A[i][j];
	  }
	  R[k][j] = r_acc;
	a_loop:
	  for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
	    A[i][j] = A[i][j] - Q[i][k] * r_acc;
	  }
	}
    }

}
}

#include "jacobi-1d.h"

void kernel_jacobi_1d(

			    double A[ N + 0],
			    double B[ N + 0])
{

    const int n = N;
    const int tsteps = TSTEPS;

  int t, i;

  for (t = 0; t < tsteps; t++)
    {
    loop_B:
      for (i = 1; i < n - 1; i++) {
#pragma HLS PIPELINE II=1
	B[i] = 0.33333 * (A[i-1] + A[i] + A[i + 1]);
      }
    loop_A:
      for (i = 1; i < n - 1; i++) {
#pragma HLS PIPELINE II=1
	A[i] = 0.33333 * (B[i-1] + B[i] + B[i + 1]);
      }
    }

}

extern "C" {
void workload(
			    double A[ N + 0],
			    double B[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_jacobi_1d(A, B);
}
}

