#include "jacobi-2d.h"

void kernel_jacobi_2d(

			    double A[ N + 0][N + 0],
			    double B[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;
    const int tsteps = TSTEPS;

  int t, i, j;

  for (t = 0; t < tsteps; t++)
    {
      for (i = 1; i < n - 1; i++)
	for (j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
	  B[i][j] = 0.2 * (A[i][j] + A[i][j-1] + A[i][1+j] + A[1+i][j] + A[i-1][j]);
        }
      for (i = 1; i < n - 1; i++)
	for (j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
	  A[i][j] = 0.2 * (B[i][j] + B[i][j-1] + B[i][1+j] + B[1+i][j] + B[i-1][j]);
        }
    }

}

