#include "ludcmp.h"


extern "C" {
void kernel_ludcmp(
		   double A[ N + 0][N + 0],
		   double b[ N + 0],
		   double x[ N + 0],
		   double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=b offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=b bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;

  double w;

  // Local staging buffers to enable fast on-chip access and partitioning
  static double A_l[N][N];
#pragma HLS ARRAY_PARTITION variable=A_l cyclic factor=8 dim=2
  static double b_l[N];
  static double x_l[N];
  static double y_l[N];
#pragma HLS ARRAY_PARTITION variable=y_l cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=x_l cyclic factor=8 dim=1

  // Stage A from global memory
LOAD_A_I:
  for (i = 0; i < n; i++) {
  LOAD_A_J:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      A_l[i][j] = A[i][j];
    }
  }
LOAD_B:
  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    b_l[i] = b[i];
  }

  // LU decomposition
  for (i = 0; i < n; i++) {
    for (j = 0; j < i; j++) {
       w = A_l[i][j];
    LU_K_LOWER:
       for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
          w -= A_l[i][k] * A_l[k][j];
       }
        A_l[i][j] = w / A_l[j][j];
    }
   for (j = i; j < n; j++) {
       w = A_l[i][j];
    LU_K_UPPER:
       for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
          w -= A_l[i][k] * A_l[k][j];
       }
       A_l[i][j] = w;
    }
  }

  // Forward substitution
  for (i = 0; i < n; i++) {
     w = b_l[i];
  FWD_J:
     for (j = 0; j < i; j++) {
#pragma HLS PIPELINE II=1
        w -= A_l[i][j] * y_l[j];
     }
     y_l[i] = w;
  }

  // Backward substitution
   for (i = n-1; i >=0; i--) {
     w = y_l[i];
  BWD_J:
     for (j = i+1; j < n; j++) {
#pragma HLS PIPELINE II=1
        w -= A_l[i][j] * x_l[j];
     }
     x_l[i] = w / A_l[i][i];
  }

  // Write results back to global memory
STORE_A_I:
  for (i = 0; i < n; i++) {
  STORE_A_J:
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      A[i][j] = A_l[i][j];
    }
  }
STORE_XY:
  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    x[i] = x_l[i];
    y[i] = y_l[i];
  }

}
}

#include "ludcmp.h"

extern "C" {
void kernel_ludcmp(
		   double A[ N + 0][N + 0],
		   double b[ N + 0],
		   double x[ N + 0],
		   double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=b offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=b bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;

  double w;

  for (i = 0; i < n; i++) {
    for (j = 0; j <i; j++) {
       w = A[i][j];
       for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
          w -= A[i][k] * A[k][j];
       }
        A[i][j] = w / A[j][j];
    }
   for (j = i; j < n; j++) {
       w = A[i][j];
       for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
          w -= A[i][k] * A[k][j];
       }
       A[i][j] = w;
    }
  }

  for (i = 0; i < n; i++) {
     w = b[i];
     for (j = 0; j < i; j++) {
#pragma HLS PIPELINE II=1
        w -= A[i][j] * y[j];
     }
     y[i] = w;
  }

   for (i = n-1; i >=0; i--) {
     w = y[i];
     for (j = i+1; j < n; j++) {
#pragma HLS PIPELINE II=1
        w -= A[i][j] * x[j];
     }
     x[i] = w / A[i][i];
  }

}
}

#include "mvt.h"


void kernel_mvt(
		double x1[ N + 0],
		double x2[ N + 0],
		double y_1[ N + 0],
		double y_2[ N + 0],
		double A[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=x1  offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x2  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=y_1 offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=y_2 offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem4

#pragma HLS INTERFACE s_axilite port=x1  bundle=control
#pragma HLS INTERFACE s_axilite port=x2  bundle=control
#pragma HLS INTERFACE s_axilite port=y_1 bundle=control
#pragma HLS INTERFACE s_axilite port=y_2 bundle=control
#pragma HLS INTERFACE s_axilite port=A   bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    int i, j;

    // Local buffers to enable reuse and parallel access
    double l_x1[N];
    double l_x2[N];
    double l_y1[N];
    double l_y2[N];
#pragma HLS ARRAY_PARTITION variable=l_y1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_y2 cyclic factor=8 dim=1

    // Stage inputs locally
load_in:
    for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        l_x1[i] = x1[i];
        l_x2[i] = x2[i];
        l_y1[i] = y_1[i];
        l_y2[i] = y_2[i];
    }

    // First loop nest: x1[i] += A[i][j] * y_1[j]
mvt1_i:
    for (i = 0; i < n; i++) {
        double acc = l_x1[i];
    mvt1_j:
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
            acc += A[i][j] * l_y1[j];
        }
        l_x1[i] = acc;
    }

    // Second loop nest: x2[i] += A[j][i] * y_2[j]
mvt2_i:
    for (i = 0; i < n; i++) {
        double acc = l_x2[i];
    mvt2_j:
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            acc += A[j][i] * l_y2[j];
        }
        l_x2[i] = acc;
    }

    // Write back results
store_out:
    for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x1[i] = l_x1[i];
        x2[i] = l_x2[i];
    }
}

#include "mvt.h"

extern "C" {
void kernel_mvt(
		double x1[ N + 0],
		double x2[ N + 0],
		double y_1[ N + 0],
		double y_2[ N + 0],
		double A[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=x1  offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x2  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=y_1 offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=y_2 offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem4

#pragma HLS INTERFACE s_axilite port=x1  bundle=control
#pragma HLS INTERFACE s_axilite port=x2  bundle=control
#pragma HLS INTERFACE s_axilite port=y_1 bundle=control
#pragma HLS INTERFACE s_axilite port=y_2 bundle=control
#pragma HLS INTERFACE s_axilite port=A   bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    int i, j;

    // Local buffers to enable parallel access and reduce AXI traffic
    double l_x1[N];
    double l_x2[N];
    double l_y1[N];
    double l_y2[N];
#pragma HLS ARRAY_PARTITION variable=l_y1 cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_y2 cyclic factor=8 dim=1

    // Load vectors into local memory
    load_loop: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        l_x1[i] = x1[i];
        l_x2[i] = x2[i];
        l_y1[i] = y_1[i];
        l_y2[i] = y_2[i];
    }

    // x1[i] = x1[i] + A[i][j] * y_1[j]
    mvt1_i: for (i = 0; i < n; i++) {
        double acc = l_x1[i];
        mvt1_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            acc += A[i][j] * l_y1[j];
        }
        l_x1[i] = acc;
    }

    // x2[i] = x2[i] + A[j][i] * y_2[j]
    mvt2_j: for (j = 0; j < n; j++) {
        double yj = l_y2[j];
        mvt2_i: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
            l_x2[i] = l_x2[i] + A[j][i] * yj;
        }
    }

    // Store results back
    store_loop: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        x1[i] = l_x1[i];
        x2[i] = l_x2[i];
    }
}
}

#include "nussinov.h"


extern "C" {

void kernel_nussinov( char seq[ N + 0],
			   int table[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=seq offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=table offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=seq bundle=control
#pragma HLS INTERFACE s_axilite port=table bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;

  // Stage inputs into local buffers to enable fast on-chip access and reuse.
  static char seq_local[N];
  static int  table_local[N][N];
#pragma HLS ARRAY_PARTITION variable=table_local cyclic factor=2 dim=2

  load_seq:
  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    seq_local[i] = seq[i];
  }

  load_table:
  for (i = 0; i < n; i++) {
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      table_local[i][j] = table[i][j];
    }
  }

 outer_i:
 for (i = n-1; i >= 0; i--) {
  inner_j:
  for (j=i+1; j<n; j++) {

   if (j-1>=0)
      table_local[i][j] = ((table_local[i][j] >= table_local[i][j-1]) ? table_local[i][j] : table_local[i][j-1]);
   if (i+1<n)
      table_local[i][j] = ((table_local[i][j] >= table_local[i+1][j]) ? table_local[i][j] : table_local[i+1][j]);

   if (j-1>=0 && i+1<n) {

     if (i<j-1)
        table_local[i][j] = ((table_local[i][j] >= table_local[i+1][j-1]+(((seq_local[i])+(seq_local[j])) == 3 ? 1 : 0)) ? table_local[i][j] : table_local[i+1][j-1]+(((seq_local[i])+(seq_local[j])) == 3 ? 1 : 0));
     else
        table_local[i][j] = ((table_local[i][j] >= table_local[i+1][j-1]) ? table_local[i][j] : table_local[i+1][j-1]);
   }

   inner_k:
   for (k=i+1; k<j; k++) {
#pragma HLS PIPELINE II=1
      table_local[i][j] = ((table_local[i][j] >= table_local[i][k] + table_local[k+1][j]) ? table_local[i][j] : table_local[i][k] + table_local[k+1][j]);
   }
  }
 }

  // Write results back to global memory.
  store_table:
  for (i = 0; i < n; i++) {
    for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      table[i][j] = table_local[i][j];
    }
  }

}

}

#include "symm.h"

void kernel_symm(
		 double alpha,
		 double beta,
		 double C[ M + 0][N + 0],
		 double A[ M + 0][M + 0],
		 double B[ M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int m = M;
    const int n = N;

    int i, j, k;

    // Stage the working set into local buffers for reuse and parallel access.
    static double C_local[M][N];
    static double A_local[M][M];
    static double B_local[M][N];
#pragma HLS ARRAY_PARTITION variable=A_local cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=B_local cyclic factor=8 dim=1

    // Load inputs into local memory.
    for (i = 0; i < M; i++) {
        for (j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            C_local[i][j] = C[i][j];
            B_local[i][j] = B[i][j];
        }
    }
    for (i = 0; i < M; i++) {
        for (j = 0; j < M; j++) {
#pragma HLS PIPELINE II=1
            A_local[i][j] = A[i][j];
        }
    }

    // Main computation. The j loop iterations are independent, so pipeline it.
    for (i = 0; i < m; i++) {
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            double temp2 = 0;
            double aii = A_local[i][i];
            double bij = B_local[i][j];
            for (k = 0; k < M; k++) {
#pragma HLS UNROLL
                if (k < i) {
                    C_local[k][j] += alpha * bij * A_local[i][k];
                    temp2 += B_local[k][j] * A_local[i][k];
                }
            }
            C_local[i][j] = beta * C_local[i][j] + alpha * bij * aii + alpha * temp2;
        }
    }

    // Store result back to global memory.
    for (i = 0; i < M; i++) {
        for (j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] = C_local[i][j];
        }
    }
}

